import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const Navbar = () => {
  const [theme, setTheme] = useState('light');
  const [showThemeDropdown, setShowThemeDropdown] = useState(false);
  const [showAboutDropdown, setShowAboutDropdown] = useState(false);

  return (
    <nav className="navbar">
      <div className="nav-container">
        <Link to="/" className="nav-logo">
          Nile Orphan Care
        </Link>
        <div className="nav-right">
          <ul className="nav-menu">
            <li><Link to="/" className="nav-link">Home</Link></li>
            <li className="dropdown" 
                onMouseEnter={() => setShowAboutDropdown(true)}
                onMouseLeave={() => setShowAboutDropdown(false)}>
              <Link to="/about" className="nav-link">About ▼</Link>
              {showAboutDropdown && (
                <div className="dropdown-menu">
                  <Link to="/about" className="dropdown-item">Our Story</Link>
                  <Link to="/about" className="dropdown-item">Mission & Vision</Link>
                  <Link to="/about" className="dropdown-item">Our Team</Link>
                  <Link to="/about" className="dropdown-item">Annual Reports</Link>
                </div>
              )}
            </li>
            <li><Link to="/programs" className="nav-link">Programs</Link></li>
            <li><Link to="/contact" className="nav-link">Contact</Link></li>
          </ul>
          <div className="nav-actions">
            <button className="search-btn">🔍</button>
            <div className="theme-dropdown"
                 onMouseEnter={() => setShowThemeDropdown(true)}
                 onMouseLeave={() => setShowThemeDropdown(false)}>
              <button className="theme-btn">🎨 ▼</button>
              {showThemeDropdown && (
                <div className="dropdown-menu">
                  <button className="dropdown-item" onClick={() => setTheme('light')}>Light</button>
                  <button className="dropdown-item" onClick={() => setTheme('dark')}>Dark</button>
                  <button className="dropdown-item" onClick={() => setTheme('blue')}>Blue</button>
                </div>
              )}
            </div>
            <Link to="/donate" className="donate-btn">Donate Now</Link>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
